// Konstanten-Zwilling MOUSE_ACTION_STAMINA_COST ist gefallen.
AnazhRealm._aktionAusdauer = function () {
    const a = AnazhRealm.Gesetz("koerper:bewegung.aktionAusdauer", null);
    if (Number.isFinite(a)) return a;
    return AnazhRealm._kernPflichtBruch("koerper:bewegung.aktionAusdauer");
};
// LANDUNGS-GEFÜHL (Zensus-Rest V18.488) — DER EINE LANDUNGS-LESER: Aufprall-
// Dip + Kamera-Glättung wohnen im koerperstudio-Gesetzbuch
// (fx.bewegung.landung). Fail-closed (Kern-Pflicht) über _bewegungsBlock.
AnazhRealm._landungGesetz = function () {
    return AnazhRealm._bewegungsBlock("landung", ["dipProV", "dipMax", "minTempo", "erholK", "kameraK"]);
};
// SCHRITT-TIMBRE (Zensus-Rest V18.488) — DER EINE TIMBRE-LESER: das
// Material→Filter-Gesetz des Schritt-Klangs wohnt im klang-Gesetzbuch
// (SCHRITT_TIMBRE — Timbre ist Klang-Wissen; die Bewegungs-Schwelle wohnt
// getrennt im koerper-Gesetzbuch). Fail-closed (Kern-Pflicht); Memo NUR im
// Erfolgs-Fall.
AnazhRealm._schrittTimbre = function () {
    if (AnazhRealm._schrittTimbreMemo) return AnazhRealm._schrittTimbreMemo;
    const t = AnazhRealm.Gesetz("klang:SCHRITT_TIMBRE", null);
    if (t && t.material && t.material.stein && typeof t.fallback === "string") {
        AnazhRealm._schrittTimbreMemo = t;
        return t;
    }
    return AnazhRealm._kernPflichtBruch("klang:SCHRITT_TIMBRE");
};
// KREATUR-SEELE (Spiegel-Zensus 17.07.) — DER EINE VERHALTENS-GESETZ-LESER:
// die Verhaltens-Zahlen der Welt-Wesen (jagd = Witterung/Biss · furcht =
// Wariness/Flucht · temperament = Signaturen/Floor/Gegenwehr-Profile ·
// wandern = Leine/Schlendern) wohnen im tetrapoda-Gesetzbuch (VERHALTEN —
// reine Daten neben aktionen/stimmung). Fail-closed (Kern-Pflicht): das
// Literal-Quartett (VERHALTEN_FALLBACK samt CREATURE_HUNT/NATURE/
// TEMPERAMENT_*/CHARAKTER) ist gefallen; die Gültigkeits-Wand deckt je
// Block ein Feld — alter Kern → Bruch, nie Misch-Gesetz. Memo NUR im
// Erfolgs-Fall.
AnazhRealm._verhaltenGesetz = function () {
    if (AnazhRealm._verhaltenGesetzMemo) return AnazhRealm._verhaltenGesetzMemo;
    try {
        const v = AnazhRealm.Gesetz("tetrapoda:VERHALTEN", null);
        if (
            v &&
            v.jagd &&
            Number.isFinite(v.jagd.strikeRange) &&
            v.furcht &&
            Number.isFinite(v.furcht.fleeThreshold) &&
            v.temperament &&
            v.temperament.signaturen &&
            v.temperament.profile &&
            Number.isFinite(v.temperament.floor) &&
            v.wandern &&
            Number.isFinite(v.wandern.leashBaseM) &&
            // SCHLUSS-WELLE (17.07.) — die neun heimgekehrten Blöcke sind
            // Kern-Pflicht: je Block deckt EIN Feld (alter Kern → Bruch,
            // nie ein Misch-Gesetz aus neuem Leser + fehlender Zeile).
            Number.isFinite(v.jagd.pirschStoppM) &&
            Number.isFinite(v.furcht.neugierStoppM) &&
            v.stimmung &&
            v.stimmung.schwellen &&
            Number.isFinite(v.stimmung.schwellen.weideDiet) &&
            v.freude &&
            Number.isFinite(v.freude.tempoMul) &&
            v.sprung &&
            Number.isFinite(v.sprung.impulsProM) &&
            Array.isArray(v.groessen) &&
            v.groessen.length >= 2 &&
            v.separation &&
            Number.isFinite(v.separation.radiusBaseM) &&
            v.aufgaben &&
            Number.isFinite(v.aufgaben.followTempo) &&
            v.herde &&
            Number.isFinite(v.herde.gewicht) &&
            v.wasser &&
            Number.isFinite(v.wasser.uferBias)
        ) {
            AnazhRealm._verhaltenGesetzMemo = v;
            return v;
        }
    } catch (_e) {}
    return AnazhRealm._kernPflichtBruch("tetrapoda:VERHALTEN");
};
AnazhRealm.STAT_FROM_TAGS = Object.freeze({
    // KAMPF-QUARTETT (Spiegel-Zensus 17.07.) — hpMax/damage/knockback/defense
    // lesen ihre Koeffizienten aus dem koerperstudio-Gesetzbuch (fx.kampf via
    // _kampfKoeff, fail-soft auf die byte-gleichen historischen Literale):
    // der Lab-Wert IST der Welt-Wert (dasselbe Muster wie speed/jumpPower).
    hpMax: (t) => {
        const K = AnazhRealm._kampfKoeff("hpMax");
        return K.base + (t.dichte || 0) * K.dichte + (t.härte || 0) * K.haerte;
    },
    damage: (t) => {
        const K = AnazhRealm._kampfKoeff("damage");
        return K.base + (t.dichte || 0) * K.dichte + (t.härte || 0) * K.haerte;
    },
    // V17.51 Kampf-Bogen Phase A (kampf-plan.md §4-A) — die Kombat-Stats EMERGIEREN
    // aus der Substanz, GENAU im bestehenden Muster (Base + Tag·Gewicht; die Tabelle
    // IST die Regel). knockback ∝ dichte (Masse stößt zurück) + härte (schwach);
    // attackSpeed ∝ (1−dichte) (leicht = schnell) + magieleitung (flink) → eine schwere
    // dichte Keule schlägt langsam-wuchtig, eine leichte harte Klinge schnell. Der
    // GAMEPLAY-Konsum (Knockback-Impuls + Angriffs-Cooldown) folgt in Phase C/D; hier
    // wird das tag-emergente Profil definiert + sichtbar gemacht (renderPlayerStatsUI).
    knockback: (t) => {
        const K = AnazhRealm._kampfKoeff("knockback");
        return K.base + (t.dichte || 0) * K.dichte + (t.härte || 0) * K.haerte;
    },
    attackSpeed: (t) => 0.8 + (1 - (t.dichte || 0)) * 0.7 + (t.magieleitung || 0) * 0.3,
    // Schöpfer-Feedback 13.05.2026 (Welle 6.D Polish): „Mensch extrem
    // langsam, evt. Basegeschwindigkeit für alle etwas höher". Base 4→6,
    // Multiplikator (1-dichte) 4→5, magieleitung 1→1.5. Mensch springt
    // von 6.1 auf ~8.75; Phönix 9.4 auf 11.2; Drache 5.0 auf 7.4. Sprint
    // = 2× Walk wirkt damit deutlicher.
    // PHYSIK-NAHT — die drei Bewegungs-Stats lesen ihre Koeffizienten aus dem
    // koerperstudio-Gesetzbuch (fx.bewegung via _bewegungsKoeff, fail-soft auf
    // die byte-gleichen historischen Literale): der Lab-Wert IST der Welt-Wert.
    speed: (t) => {
        const K = AnazhRealm._bewegungsKoeff("speed");
        return K.base + (1 - (t.dichte || 0)) * K.leicht + (t.magieleitung || 0) * K.mag;
    },
    jumpPower: (t) => {
        const K = AnazhRealm._bewegungsKoeff("jumpPower");
        return K.base + (1 - (t.dichte || 0)) * K.leicht + (t.magieleitung || 0) * K.mag;
    },
    staminaMax: (t) => {
        const K = AnazhRealm._bewegungsKoeff("staminaMax");
        return K.base + (1 - (t.dichte || 0)) * K.leicht + (t.wärmeleitung || 0) * K.mag;
    },
    // V18.196 — MANA-SYMMETRIE: die zweite Ausdauer-Achse, treibt aus
    // magieleitung statt aus (1-dichte). Symmetrisch zu staminaMax: base 50
    // + magieleitung·100 (max ~150 bei voll magieleitung) + resoniert·30
    // (Sekundär-Boost — eine resonante Substanz hat eine offenere Mana-
    // Bandbreite). Mensch (magieleitung 0, resoniert 0) → 50 Default; Drache
    // (magieleitung ~0.3) → ~80; Phönix (magieleitung ~0.6 + resoniert ~0.3)
    // → ~119. Eine Welt-Stimme, die schlief, wird zur zweiten Lebens-Achse.
    manaMax: (t) => 50 + (t.magieleitung || 0) * 100 + (t.resoniert || 0) * 30,
    precision: (t) => 0.5 + (t.magieleitung || 0) * 0.3 + (t.zähigkeit || 0) * 0.2,
    magicResist: (t) => (t.magieleitung || 0) * 0.4 + (t.resoniert || 0) * 0.3,
    heatResist: (t) => (t.wärmeleitung || 0) * 0.5 - (t.brennbar || 0) * 0.3,
    // V17.51 Kampf-Bogen Phase A — defense (PHYSISCH) ∝ dichte + härte (dichte, harte
    // Rüstung blockt); ergänzt magicResist/heatResist (elementar) zum vollständigen
    // Defense-Trio. Base-los wie die elementaren Resists (ein weiches Wesen blockt ~0).
    // Konsum als flache Schadens-Reduktion (dealt = max(1, amount − defense)) in Phase C.
    defense: (t) => {
        const K = AnazhRealm._kampfKoeff("defense");
        return K.base + (t.dichte || 0) * K.dichte + (t.härte || 0) * K.haerte;
    },
});

// SYNERGIE-WELLE — die AURA_TAG_HUE-Map ist mit der Avatar-Aura GEFALLEN
// (Schoepfer: keine Avatar-Aura im Nervensystem; die Tag-Achsen sprechen
// weiter durch Substanz/Resonanz/Werkstatt-Chips — nicht durch einen Glow).

// Welle 6.D Etappe 3b — Stat-Stacking-Gewichte. Compound-Tags der ausge-
// rüsteten Werkzeuge/Rüstung werden zur Soul-Tag-Basis addiert, dann läuft
// STAT_FROM_TAGS. armor 0.3 = Rüstung trägt spürbar, ersetzt Seele nicht;
// tool 0.15 = Werkzeug-in-Hand wirkt nur leicht; weapon/held 0.4 = die
// Waffe/das EINE gehaltene Gerät prägt STARK (der Kern von Schaden/
// Rückschlag/Tempo; TOOL/WEAPON bleiben der getrennte KREATUR-Equip-Fold).
// ZENSUS-REST V18.488 — die vier Gewichte wohnen im koerperstudio-Gesetzbuch
// (koerper:kampf.fold via _kampfFold, fail-closed); die Statics sind LESER.
Object.defineProperties(AnazhRealm, {
    ARMOR_STAT_WEIGHT: {
        get() {
            return AnazhRealm._kampfFold().armor;
        },
    },
    TOOL_STAT_WEIGHT: {
        get() {
            return AnazhRealm._kampfFold().tool;
        },
    },
    WEAPON_STAT_WEIGHT: {
        get() {
            return AnazhRealm._kampfFold().weapon;
        },
    },
    HELD_STAT_WEIGHT: {
        get() {
            return AnazhRealm._kampfFold().held;
        },
    },
});
// V17.73 S9 (kampf-plan §10-F4) — das gehaltene Gerät SICHTBAR in der Hand: die Optik des
// „in der Hand"-Geräts. Reuse von _buildFromBlueprint (kein Parallel-Pfad) → ein Mesh am
// rechten Arm/Flügel des Avatars (schwingt mit dem _animateHuman-Walk-Cycle via der THREE-
// Transform-Kette) bzw. an der Körper-Wurzel (Fallback für Custom-Seelen ohne benannten Arm).
// Alle Werte browser-justierbar — die Pose/Skala/der Sitz in der Hand sind das Schöpfer-Auge;
// headless beweist nur Existenz + Lifecycle + Anker (V13-Render-Lehre, pixel-blind).
AnazhRealm.HELD_MESH = Object.freeze({
    targetSpanM: 0.62, // die längste Dimension des Geräts in der Hand (auf Werkzeug-Größe skaliert)
    minScale: 0.04,
    maxScale: 3,
    handOffset: Object.freeze({ x: 0, y: -0.5, z: 0.12 }), // im Arm-Anker-Lokalraum (Handfläche/-spitze)
    rootOffset: Object.freeze({ x: 0.42, y: 0.9, z: 0.32 }), // Fallback: vorn-rechts an der Körper-Wurzel
    tilt: Object.freeze({ x: 0.5, y: 0, z: 0 }), // ein leichter Vorwärts-Neigung (ein langes Werkzeug zeigt nach vorn/unten)
});
// V17.54 Kampf-Bogen Phase D — die Reichweite des Spieler-Nahangriffs liest
// das schmiede-Gesetz (ARENA.schwung.reachMaxM via _arenaGesetz); der
// Konstanten-Zwilling COMBAT_REACH_M ist gefallen (Kern-Pflicht).
// ═══ KAMPF-GEFÜHL (Orakel Tier-1 #5) — DIE GESETZE DES SCHWUNGS ═══
// Die EINE Schwung-Dauer-Quelle ist die GERECHNETE Trägheit (_swingDynamics,
// Ω-Φ4: I = Σ m·r² um den Griff): Gesamt-Dauer = dauerProSqrtI·√I, geklemmt.
// Die attackSpeed-Parallel-Wahrheit (Material-Tags) ist für den SPIELER-Schwung
// gefallen — Cooldown/HUD/Werkstatt lesen diese Quelle (die Kreaturen behalten
// das tag-emergente Profil: ihr Körper IST ihre Substanz). Feel-Werte browser-
// justierbar; die MECHANIK (∝ √I · Sweep-Wände · Hit-Stop ≠ Sim) hält
// gate:kampf-gefuehl.
// SPIEGEL-ZENSUS 17.07. / KERN-PFLICHT 17.07. — die Zahlen-Tabellen sind
// GEFALLEN: Dauer + Hieb-GEOMETRIE (Phasen, Sweep-Bogen, Klingen-Radius,
// Reichweite, Schulter, Tod-Kippen), Stoss/Hit-Stop/Dip und die Pfeil-Flug-
// Physik wohnen im schmiede-Gesetzbuch (ARENA.schwung/.gefuehl/.bogen/.guete),
// alle Konsumenten lesen _arenaGesetz() — fail-closed, kein SWING_LAWS/
// BOGEN_LAWS/ARENA_FALLBACK-Zwilling mehr. maxPfeile blieb ehrlich WIRTS-
// Infrastruktur (Perf-Deckel lebender Pfeile, kein Gefühls-Gesetz):
AnazhRealm.MAX_PFEILE = 16;
// ═══ ARENA-GEFÜHL (Schöpfer-Vertrags-Akt 16.07.) — DER EINE GEFÜHLS-LESER ═══
// Die Gefühls-Gesetze der schmiede-Arena (Schwung-Konstanten · energie-
// skalierter Hit-Stop/Dip · die EINE Bogen-Physik + der Auszug · Waffen-Güte)
// wohnen im schmiede-Gesetzbuch (__schmiedeCore.ARENA). Fail-closed
// (Kern-Pflicht); Memo NUR im Erfolgs-Fall.
AnazhRealm._arenaGesetz = function () {
    if (AnazhRealm._arenaGesetzMemo) return AnazhRealm._arenaGesetzMemo;
    const a = AnazhRealm.Gesetz("schmiede:ARENA", null);
    // Die Gültigkeits-Wand deckt je Block EIN Zensus-Feld mit: ein ALTER
    // Kern ohne die gereisten Zeilen ist ein BRUCH, nie ein Misch-Gesetz
    // aus halb Kern / halb undefined.
    if (
        a &&
        a.schwung &&
        a.gefuehl &&
        a.bogen &&
        Number.isFinite(a.schwung.dauerProSqrtI) &&
        Number.isFinite(a.schwung.windupFrac) &&
        Number.isFinite(a.gefuehl.stossCap) &&
        Number.isFinite(a.bogen.muendungM)
    ) {
        AnazhRealm._arenaGesetzMemo = a;
        return a;
    }
    return AnazhRealm._kernPflichtBruch("schmiede:ARENA");
};

// Welle 6.D Etappe 3a+ (Schöpfer-Feedback 13.05.2026) — Werkzeug-Anwendung
